var lookupWhyCommitInfo = func(ctx context.Context, hash string) (whyCommitInfo, *git.Repository, id.CheckpointID, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return whyCommitInfo{}, nil, id.EmptyCheckpointID, err
	}

	resolvedHash, err := resolveCommitUnambiguous(repo, hash)
	if err != nil {
		return whyCommitInfo{}, nil, id.EmptyCheckpointID, err
	}

	commit, err := repo.CommitObject(resolvedHash)
	if err != nil {
		return whyCommitInfo{}, nil, id.EmptyCheckpointID, err
	}

	info := whyCommitInfo{
		Hash:      resolvedHash.String(),
		ShortHash: shortCommitHash(resolvedHash.String()),
		Author:    commit.Author.Name,
		Email:     commit.Author.Email,
		WhenText:  commit.Author.When.Local().Format("2006-01-02 15:04:05"),
		Subject:   commitSubject(commit.Message),
	}

	checkpointID, hasCheckpoint := trailers.ParseCheckpoint(commit.Message)
	if !hasCheckpoint {
		return info, repo, id.EmptyCheckpointID, nil
	}

	return info, repo, checkpointID, nil
}

func enrichWhyBlocks(ctx context.Context, blocks []whyBlock) ([]whyBlock, error) {
	if len(blocks) == 0 {
		return nil, nil
	}

	uniqueHashes := make([]string, 0, len(blocks))
	seen := make(map[string]struct{}, len(blocks))
	for _, block := range blocks {
		if block.Commit.Hash == "" {
			continue
		}
		if _, ok := seen[block.Commit.Hash]; ok {
			continue
		}
		seen[block.Commit.Hash] = struct{}{}
		uniqueHashes = append(uniqueHashes, block.Commit.Hash)
	}

	resolved := make(map[string]struct {
		commit whyCommitInfo
		entire *whyEntireInfo
	}, len(uniqueHashes))
	for _, hash := range uniqueHashes {
		commit, entire, err := resolveWhyCommitMetadata(ctx, hash)
		if err != nil {
			return nil, err
		}
		resolved[hash] = struct {
			commit whyCommitInfo
			entire *whyEntireInfo
		}{commit: commit, entire: entire}
	}

	out := make([]whyBlock, len(blocks))
	copy(out, blocks)
	for i := range out {
		block := out[i]
		if block.Commit.Hash == "" {
			continue
		}
		resolution, ok := resolved[block.Commit.Hash]
		if !ok {
			continue
		}
		out[i].Commit = resolution.commit
		if resolution.entire != nil {
			out[i].Entire = resolution.entire
		}
	}

	return out, nil
}

var loadWhyDisplayData = loadWhyDisplayDataImpl

var writeWhyStaticOutput = func(w io.Writer, content string) error {
	_, err := fmt.Fprint(w, content)
	return err
}

func loadWhyDisplayDataImpl(ctx context.Context, path string) ([]whyBlock, error) {
	blocks, err := loadWhyBlocks(ctx, path)
	if err != nil {
		return nil, err
	}
	return enrichWhyBlocks(ctx, blocks)
}

var resolveWhyCommitMetadata = func(ctx context.Context, hash string) (whyCommitInfo, *whyEntireInfo, error) {
	info, repo, checkpointID, err := lookupWhyCommitInfo(ctx, hash)
	if err != nil {
		return whyCommitInfo{}, nil, err
	}
	if checkpointID.IsEmpty() {
		return info, nil, nil
	}

	entire, err := lookupWhyCheckpointInfo(ctx, repo, checkpointID, info.Subject)
	if err != nil {
		return info, nil, err
	}

	return info, entire, nil
}

var lookupWhyCheckpointInfo = func(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
	if repo == nil {
		var err error
		repo, err = openRepository(ctx)
		if err != nil {
			return nil, err
		}
	}

	v1Store := checkpoint.NewGitStore(repo)
	v2Store := checkpoint.NewV2GitStore(repo, "origin")

	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpointID, v1Store, v2Store, true)
	if err != nil {
		return nil, err
	}

	return loadWhyEntireInfo(ctx, reader, summary, checkpointID, commitSubject)
}

var loadWhyEntireInfo = loadWhyEntireInfoImpl

func loadWhyEntireInfoImpl(ctx context.Context, reader checkpoint.CommittedReader, summary *checkpoint.CheckpointSummary, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
	if summary == nil {
		return nil, nil
	}

	sessionIndex := len(summary.Sessions) - 1
	if sessionIndex < 0 {
		return &whyEntireInfo{
			CheckpointID: checkpointID.String(),
			Summary:      commitSubject,
			IsFallback:   true,
		}, nil
	}

	sessionMetadata, err := readWhySessionMetadata(ctx, reader, checkpointID, sessionIndex)
	if err != nil {
		return nil, err
	}
	if sessionMetadata == nil {
		return &whyEntireInfo{
			CheckpointID: checkpointID.String(),
			Summary:      commitSubject,
			IsFallback:   true,
		}, nil
	}

	summaryText, isFallback := selectWhySummary(sessionMetadata.Summary, commitSubject)
	return &whyEntireInfo{
		CheckpointID: checkpointID.String(),
		Agent:        string(sessionMetadata.Agent),
		Summary:      summaryText,
		IsFallback:   isFallback,
	}, nil
}

var readWhySessionMetadata = func(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}

	switch r := reader.(type) {
	case interface {
		ReadSessionMetadata(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error)
	}:
		return r.ReadSessionMetadata(ctx, checkpointID, sessionIndex)
	case interface {
		ReadSessionMetadataAndPrompts(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.SessionContent, error)
	}:
		content, err := r.ReadSessionMetadataAndPrompts(ctx, checkpointID, sessionIndex)
		if err != nil {
			return nil, err
		}
		if content == nil {
			return nil, nil
		}
		return &content.Metadata, nil
	default:
		return nil, fmt.Errorf("reader does not support metadata-only session reads")
	}
}

func selectWhySummary(summary *checkpoint.Summary, commitSubject string) (string, bool) {
	if summary != nil {
		if text := strings.TrimSpace(summary.Outcome); text != "" {
			return text, false
		}
		if text := strings.TrimSpace(summary.Intent); text != "" {
			return text, true
		}
	}

	if text := strings.TrimSpace(commitSubject); text != "" {
		return text, true
	}

	return "", true
}

func commitSubject(message string) string {
	subject, _, found := strings.Cut(message, "\n")
	if found {
		return strings.TrimSpace(subject)
	}
	return strings.TrimSpace(message)
}

