func loadWhyDisplayDataImpl(ctx context.Context, path string) ([]whyBlock, error) {
	blocks, err := loadWhyBlocks(ctx, path)
	if err != nil {
		return nil, err
	}

	enriched, enrichErr := enrichWhyBlocks(ctx, blocks)
	if enrichErr != nil {
		if !errors.Is(enrichErr, errWhyOptionalCheckpointMetadata) {
			return nil, enrichErr
		}
		return blocks, nil
	}

	return enriched, nil
}

var resolveWhyCommitMetadata = func(ctx context.Context, hash string) (whyCommitInfo, *whyEntireInfo, error) {
	info, repo, checkpointID, err := lookupWhyCommitInfo(ctx, hash)
	if err != nil {
		return whyCommitInfo{}, nil, err
	}
	if checkpointID.IsEmpty() {
		return info, nil, nil
	}

	entire, err := lookupWhyCheckpointInfo(ctx, repo, checkpointID, info.Subject)
	if err != nil {
		return info, nil, err
	}

	return info, entire, nil
}

var lookupWhyCheckpointInfo = func(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
	if repo == nil {
		var err error
		repo, err = openRepository(ctx)
		if err != nil {
			return nil, err
		}
	}

	v1Store := checkpoint.NewGitStore(repo)
	v2Store := checkpoint.NewV2GitStore(repo, "origin")

	reader, summary, err := checkpoint.ResolveCommittedReaderForCheckpoint(ctx, checkpointID, v1Store, v2Store, true)
	if err != nil {
		if errors.Is(err, checkpoint.ErrCheckpointNotFound) {
			return nil, fmt.Errorf("%w: %w", errWhyOptionalCheckpointMetadata, err)
		}
		return nil, err
	}

	return loadWhyEntireInfo(ctx, reader, summary, checkpointID, commitSubject)
}

var loadWhyEntireInfo = loadWhyEntireInfoImpl

func loadWhyEntireInfoImpl(ctx context.Context, reader checkpoint.CommittedReader, summary *checkpoint.CheckpointSummary, checkpointID id.CheckpointID, commitSubject string) (*whyEntireInfo, error) {
	if summary == nil {
		return nil, nil
	}

	sessionIndex := len(summary.Sessions) - 1
	if sessionIndex < 0 {
		return &whyEntireInfo{
			CheckpointID: checkpointID.String(),
			Summary:      commitSubject,
			IsFallback:   true,
		}, nil
	}

	sessionMetadata, err := readWhySessionMetadata(ctx, reader, checkpointID, sessionIndex)
	if err != nil {
		return nil, err
	}
	if sessionMetadata == nil {
		return &whyEntireInfo{
			CheckpointID: checkpointID.String(),
			Summary:      commitSubject,
			IsFallback:   true,
		}, nil
	}

	summaryText, isFallback := selectWhySummary(sessionMetadata.Summary, commitSubject)
	return &whyEntireInfo{
		CheckpointID: checkpointID.String(),
		Agent:        string(sessionMetadata.Agent),
		Summary:      summaryText,
		IsFallback:   isFallback,
	}, nil
}

var readWhySessionMetadata = func(ctx context.Context, reader checkpoint.CommittedReader, checkpointID id.CheckpointID, sessionIndex int) (*checkpoint.CommittedMetadata, error) {
	if err := ctx.Err(); err != nil {
