+func TestLoadWhyDisplayData_PreservesSuccessfulEnrichmentsWithOptionalMetadataMiss(t *testing.T) {
+	origBlame := runGitBlamePorcelain
+	origLookupCommit := lookupWhyCommitInfo
+	origLookupCheckpoint := lookupWhyCheckpointInfo
+	t.Cleanup(func() {
+		runGitBlamePorcelain = origBlame
+		lookupWhyCommitInfo = origLookupCommit
+		lookupWhyCheckpointInfo = origLookupCheckpoint
+	})
+
+	runGitBlamePorcelain = func(_ context.Context, _, path string) (string, error) {
+		if path != "cmd/entire/cli/why.go" {
+			t.Fatalf("path = %q, want %q", path, "cmd/entire/cli/why.go")
+		}
+		return strings.Join([]string{
+			"b550507521111111111111111111111111111111 12 11 1",
+			"author Victor Gutierrez",
+			"summary Handle interrupt signals",
+			"\tpackage main",
+			"7f93a963e3222222222222222222222222222222 24 24 1",
+			"author Stefan Haubold",
+			"summary Improve CLI error handling",
+			"\tvar silent *cli.SilentError",
+		}, "\n"), nil
+	}
+	lookupWhyCommitInfo = func(_ context.Context, hash string) (whyCommitInfo, *git.Repository, id.CheckpointID, error) {
+		switch hash {
+		case "b550507521111111111111111111111111111111":
+			return whyCommitInfo{
+				Hash:      hash,
+				ShortHash: "b550507521",
+				Author:    "Victor Gutierrez",
+				Subject:   "Handle interrupt signals",
+			}, nil, id.MustCheckpointID("a3b2c4d5e6f7"), nil
+		case "7f93a963e3222222222222222222222222222222":
+			return whyCommitInfo{
+				Hash:      hash,
+				ShortHash: "7f93a963e3",
+				Author:    "Stefan Haubold",
+				Subject:   "Improve CLI error handling",
+			}, nil, id.MustCheckpointID("d4e5f6a7b8c9"), nil
+		default:
+			t.Fatalf("unexpected hash lookup: %s", hash)
+			return whyCommitInfo{}, nil, id.EmptyCheckpointID, nil
+		}
+	}
+	lookupWhyCheckpointInfo = func(_ context.Context, _ *git.Repository, checkpointID id.CheckpointID, _ string) (*whyEntireInfo, error) {
+		if checkpointID.String() == "a3b2c4d5e6f7" {
+			return nil, errors.Join(errWhyOptionalCheckpointMetadata, context.DeadlineExceeded)
+		}
+		if checkpointID.String() == "d4e5f6a7b8c9" {
+			return &whyEntireInfo{
+				CheckpointID: checkpointID.String(),
+				Agent:        "Claude Code",
+				Summary:      "Improve CLI error handling",
+				IsFallback:   true,
+			}, nil
+		}
+		t.Fatalf("unexpected checkpoint id: %s", checkpointID)
+		return nil, nil
+	}
+
+	blocks, err := loadWhyDisplayData(context.Background(), "cmd/entire/cli/why.go")
+	if err != nil {
+		t.Fatalf("load display data error: %v", err)
+	}
+	if len(blocks) != 2 {
+		t.Fatalf("block count = %d, want 2", len(blocks))
+	}
+	if blocks[0].Entire != nil {
+		t.Fatal("expected first block to stay commit-only")
+	}
+	if blocks[1].Entire == nil {
+		t.Fatal("expected second block to remain enriched")
+	}
+	if got, want := blocks[0].Commit.Author, "Victor Gutierrez"; got != want {
+		t.Fatalf("first author = %q, want %q", got, want)
+	}
+	if got, want := blocks[1].Entire.Agent, "Claude Code"; got != want {
+		t.Fatalf("second agent = %q, want %q", got, want)
+	}
