+func TestWhyCommand_StaticModePropagatesWriteError(t *testing.T) {
+	origLoad := loadWhyDisplayData
+	origWrite := writeWhyStaticOutput
+	t.Cleanup(func() { loadWhyDisplayData = origLoad })
+	t.Cleanup(func() { writeWhyStaticOutput = origWrite })
+
+	loadWhyDisplayData = func(_ context.Context, _ string) ([]whyBlock, error) {
+		return []whyBlock{{
+			Commit:    whyCommitInfo{ShortHash: "7f93a963e3"},
+			CodeLines: []string{"package main"},
+		}}, nil
+	}
+	writeWhyStaticOutput = func(_ io.Writer, _ string) error {
+		return io.ErrClosedPipe
+	}
+
+	cmd := newWhyCmd()
+	var out bytes.Buffer
+	cmd.SetOut(&out)
+	cmd.SetErr(&out)
+	cmd.SetArgs([]string{"cmd/entire/main.go"})
+
+	err := cmd.Execute()
+	if err == nil {
+		t.Fatal("expected write error")
+	}
+	if !strings.Contains(err.Error(), "writing why output") {
+		t.Fatalf("error = %v, want write output context", err)
+	}
+	if !strings.Contains(err.Error(), io.ErrClosedPipe.Error()) {
+		t.Fatalf("error = %v, want wrapped broken pipe", err)
+	}
